    const k = j * cols + i;
    const stag = (j % 2) * 0.5;
    const isStoma = fr(k * 3 + 1) < (0.12 + P.aperture * 0.22);
    const base = {
      gx: (i + 0.5 + stag) / cols, gy: (j + 0.5) / rows,
      jx: (fr(k * 5 + 2) - 0.5) * 0.5 / cols, jy: (fr(k * 7 + 3) - 0.5) * 0.5 / rows,
      hj: (fr(k * 11 + 4) - 0.5) * 22
